"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$archiveCheck = @'"'
const fs = require('node:fs');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const original = fs.readFileSync('draft-summary.md');
const archived = fs.readFileSync('handoff/original-summary.md');
assert.deepEqual(archived, original);
const digest = crypto.createHash('sha256').update(archived).digest('hex').toUpperCase();
assert.equal(digest, '4A7277EBEE0F9597A1E066107380540C66590C6B81304218C91DC46CFD2135D4');
process.stdout.write(JSON.stringify({archive_byte_comparison: 'PASS', bytes: archived.length, sha256: digest}) + '\\n');
'@
"'$archiveCheck | node
Get-FileHash -Algorithm SHA256 -LiteralPath '"'README.md','draft-summary.md','study/protocol.md','evidence/reference.csv','evidence/guide.csv','evidence/pairs.csv','evidence/capture-notes.md','guides/reference-card.txt','guides/reorganized-guide.txt','tools/check-evidence.cjs','audit/findings.md','audit/metrics.json' | Select-Object Path, Hash | ConvertTo-Json -Depth 3"

"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$handoffText = Get-Content -LiteralPath '"'handoff/methods.md' -Raw
"'$codeBlock = [regex]::Match($handoffText, '"'(?s)"'```powershell'"\\r?\\n(.*?)\\r?\\n"'```'"')
if ("'!$codeBlock.Success) { throw '"'Reproduction code block missing' }
"'$printedLines = @(& ([scriptblock]::Create($codeBlock.Groups[1].Value)))
$printedText = $printedLines -join [Environment]::NewLine
$jsonStart = $printedText.LastIndexOf('"'{')
if ("'$jsonStart -lt 0) { throw '"'No metrics JSON was printed' }
"'$recomputed = $printedText.Substring($jsonStart) | ConvertFrom-Json
$savedMetrics = Get-Content -LiteralPath '"'audit/metrics.json' -Raw | ConvertFrom-Json
"'$recomputedKeys = @($recomputed.PSObject.Properties.Name)
$savedKeys = @($savedMetrics.PSObject.Properties.Name)
if (@(Compare-Object -ReferenceObject $savedKeys -DifferenceObject $recomputedKeys).Count -ne 0) { throw '"'Reproduction fields differ from audit metrics' }
foreach ("'$key in $savedKeys) {
  if ($recomputed.$key.GetType().Name -notin @('"'Int32','Int64','Double','Decimal') -or "'$recomputed.$key -ne $savedMetrics.$key) { throw "Reproduction mismatch: $key" }
}
$documentJson = [regex]::Match($handoffText, '"'(?s)"'```json'"\\r?\\n(.*?)\\r?\\n"'```'"')
"'$documentMetrics = $documentJson.Groups[1].Value | ConvertFrom-Json
foreach ($key in $savedKeys) { if ($documentMetrics.$key -ne $savedMetrics.$key) { throw "Document JSON mismatch: $key" } }
$linkTargets = [regex]::Matches($handoffText, '"'\\]\\((["'^)]+)'"\\)')
foreach ("'$linkTarget in $linkTargets) {
  $targetPath = Join-Path -Path '"'handoff' -ChildPath "'$linkTarget.Groups[1].Value
  if (!(Test-Path -LiteralPath $targetPath -PathType Leaf)) { throw "Broken handoff link: $targetPath" }
}
[PSCustomObject]@{ verification = '"'PASS'; reproduction_numeric_fields = "'$savedKeys.Count; embedded_json_matches_audit = $true; local_links_checked = $linkTargets.Count; metrics = $recomputed } | ConvertTo-Json -Depth 4'
